package org.thesandbox.core.util;

import java.io.IOException;
import java.io.InputStream;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Properties;
import java.util.Set;

/**
 * Read-only view of the build flavor generated by Gradle.
 *
 * <p>The generated {@code flavor.properties} contains three allowlists:
 * {@code commands}, {@code items} and {@code features}. A value of {@code *}
 * means "everything", an empty value means "nothing", and a comma-separated
 * list enables only those entries. When the resource is missing (for example
 * when running from an IDE without Gradle resource processing), the full
 * sandbox feature set is used.</p>
 */
public final class BuildFlavor {

    private static final String DEFAULT_FLAVOR = "sandbox";
    private static final Properties PROPERTIES = new Properties();

    private static final String FLAVOR;
    private static final String DISPLAY_NAME;
    private static final Set<String> COMMANDS;
    private static final Set<String> ITEMS;
    private static final Set<String> FEATURES;

    static {
        try (InputStream in = BuildFlavor.class.getResourceAsStream("/flavor.properties")) {
            if (in != null) {
                PROPERTIES.load(in);
            }
        } catch (IOException ignored) {
            // Fall back to the full sandbox feature set.
        }

        FLAVOR = normalize(PROPERTIES.getProperty("flavor", DEFAULT_FLAVOR));
        DISPLAY_NAME = PROPERTIES.getProperty("display-name", FLAVOR).trim();
        COMMANDS = parseAllowlist(PROPERTIES.getProperty("commands", "*"));
        ITEMS = parseAllowlist(PROPERTIES.getProperty("items", "*"));
        FEATURES = parseAllowlist(PROPERTIES.getProperty("features", "*"));
    }

    private BuildFlavor() {
    }

    /** Machine name of the flavor, for example {@code survival}. */
    public static String name() {
        return FLAVOR;
    }

    /** Human-readable name from the flavor file. */
    public static String displayName() {
        return DISPLAY_NAME;
    }

    public static boolean hasCommandAllowlist() {
        return COMMANDS != null;
    }

    public static boolean isCommandEnabled(String command) {
        return isEnabled(COMMANDS, command);
    }

    public static boolean isItemEnabled(String item) {
        return isEnabled(ITEMS, item);
    }

    public static boolean isItemEnabled(Class<?> itemClass) {
        return itemClass != null && isEnabled(ITEMS, itemId(itemClass));
    }

    public static boolean isFeatureEnabled(String feature) {
        return isEnabled(FEATURES, feature);
    }

    /** One-line summary used in the startup log. */
    public static String summary() {
        return DISPLAY_NAME + " [" + FLAVOR + "]"
                + " commands=" + describe(COMMANDS)
                + ", items=" + describe(ITEMS)
                + ", features=" + describe(FEATURES);
    }

    private static boolean isEnabled(Set<String> allowlist, String value) {
        if (allowlist == null) {
            return true;
        }
        return value != null && allowlist.contains(normalize(value));
    }

    /** {@code *} returns {@code null} (all); empty returns an empty set (none). */
    private static Set<String> parseAllowlist(String raw) {
        String value = raw == null ? "" : raw.trim();
        if (value.equals("*")) {
            return null;
        }
        if (value.isEmpty()) {
            return Set.of();
        }

        Set<String> result = new LinkedHashSet<>();
        for (String part : value.split(",")) {
            String normalized = normalize(part);
            if (!normalized.isEmpty()) {
                result.add(normalized);
            }
        }
        return Collections.unmodifiableSet(result);
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
    }

    private static String describe(Set<String> allowlist) {
        if (allowlist == null) {
            return "*";
        }
        return allowlist.isEmpty() ? "none" : String.valueOf(allowlist.size());
    }

    /** {@code WindRodItem -> wind-rod}, {@code Rideable_Ender_Pearl_Item -> rideable-ender-pearl}. */
    private static String itemId(Class<?> itemClass) {
        String simple = itemClass.getSimpleName();
        if (simple.endsWith("Item")) {
            simple = simple.substring(0, simple.length() - "Item".length());
        }
        simple = simple.replace('_', '-');
        return simple.replaceAll("([a-z0-9])([A-Z])", "$1-$2").toLowerCase(Locale.ROOT);
    }
}
